import{_ as o,r as n,o as p,c as i,e as a,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Model Settings - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Database Settings","slug":"database-settings","link":"#database-settings","children":[{"level":3,"title":"Model Class Definition","slug":"model-class-definition","link":"#model-class-definition","children":[]}]},{"level":2,"title":"Writing to a Settings Model","slug":"writing-to-a-settings-model","link":"#writing-to-a-settings-model","children":[]},{"level":2,"title":"Reading From a Settings Model","slug":"reading-from-a-settings-model","link":"#reading-from-a-settings-model","children":[]},{"level":2,"title":"Integration with Multisite","slug":"integration-with-multisite","link":"#integration-with-multisite","children":[]}],"relativePath":"3.x/extend/settings/model-settings.md","filePath":"3.x/extend/settings/model-settings.md"}'),r={name:"3.x/extend/settings/model-settings.md"};function d(u,s,g,k,m,h){const e=n("pre-heading"),t=n("post-heading");return p(),i("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Model Settings",-1)),a(t),s[1]||(s[1]=c(`<p>Model settings keep values stored in the database and can be overriden by the user interface in the backend panel.</p><h2 id="database-settings"><a href="#database-settings" class="header-anchor">#</a> Database Settings</h2><p>Plugins can use database-driven configuration using models for storing settings in the database by extending the <code>System\\Models\\SettingModel</code> base class. This model can be used directly for creating the backend settings form. You don&#39;t need to create a database table and a controller for creating the backend settings forms based on the settings model. An example of a model setting directory structure:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── demo
|           ├── models
|           |   ├── usersetting  <em>← Config Directory</em>
|           |   |   └── fields.yaml  <em>← Form Fields</em>
|           |   └── <code>UserSetting.php</code>  <em>← Model Class</em>
|           └── Plugin.php</p>
</code></pre><p>Settings models can be registered to appear on the <a href="./settings.html">settings area in the backend panel</a>, but it is not a requirement - you can set and read settings values like any other model.</p><h3 id="model-class-definition"><a href="#model-class-definition" class="header-anchor">#</a> Model Class Definition</h3><p>The settings model classes should extend the <code>System\\Models\\SettingModel</code> class, and like any other model, should be defined in the <strong>models</strong> subdirectory of the plugin directory. The model from the next example should be defined in the <strong>plugins/acme/demo/models/UserSetting.php</strong> file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">UserSetting</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>SettingModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>$settingsCode</code> property is required for settings models. It defines the unique settings key which is used for saving the settings to the database.</p><p>The <code>$settingsFields</code> property is required if you are going to build a backend settings form based on the model. The property specifies a name of the YAML file containing the form fields definition. The form fields are described in the <a href="./../forms/form-controller.html">form controller article</a>. The YAML file should be placed to the directory with the name matching the model class name in lowercase.</p><h2 id="writing-to-a-settings-model"><a href="#writing-to-a-settings-model" class="header-anchor">#</a> Writing to a Settings Model</h2><p>The settings model has the static <code>set</code> method that allows to save individual or multiple values. You can also use the standard model features for setting the model properties and saving the model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token punctuation">;</span>

<span class="token comment">// Set a single value</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set an array of values</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set object values</span>
<span class="token variable">$settings</span> <span class="token operator">=</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token property">api_key</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="reading-from-a-settings-model"><a href="#reading-from-a-settings-model" class="header-anchor">#</a> Reading From a Settings Model</h2><p>The settings model has the static <code>get</code> method that enables you to load individual properties. Also, when you instantiate a model with the <code>instance</code> method, it loads the properties from the database and you can access them directly.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Outputs: ABCD</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">api_key</span><span class="token punctuation">;</span>

<span class="token comment">// Get a single value</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Get a value and return a default value if it doesn&#39;t exist</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_activated&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="integration-with-multisite"><a href="#integration-with-multisite" class="header-anchor">#</a> Integration with Multisite</h2><p>Settings models can provide different configuration values for each site defined by <a href="./../../cms/resources/multisite.html">multisite configuration</a>. To enable multisite, include the <code>October\\Rain\\Database\\Traits\\Multisite</code> <a href="./../database/traits.html">trait</a> inside the model and define a <code>$propagatable</code> property, which can specify fields that propagate across all sites.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">UserSetting</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>SettingModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,19))])}const y=o(r,[["render",d]]);export{b as __pageData,y as default};
